  Sparql 1)  
  PREFIX dc: < http://purl.org/dc/elements/1.1/>  
  PREFIX foaf: < http://xmlns.com/foaf/0.1/>  

  SELECT ?bookTitle  
  WHERE {  
  ?book a dc:Book .  
  ?book dc:creator ?author .  
  ?author a foaf:Person .  
  ?author foaf:name "Jane Austen" .  
  ?book dc:title ?bookTitle .  
  }  
